-- Descrição: 

INSERT INTO TempVendaImovel ( LinkVenda, CodAnteriorParceiro, EmpVinculada, CodigoParceiro, DataMovto, CodImovel, CodHistorico, Plano3, ContaFinanceira, NumDoc, Complemento, ValorCredito, AgrupadorVenda, DataVencto, Integracao, ClassificacaoVenda, CodAtribuiParceiro, Efetuado, IndiceReajuste, SofreReajuste, ValorOriginalImovel, CodigoCondPagto )
SELECT Formulários!VendaImovelVendido!VendaCondPagto.Formulário!LinkVenda AS Link, "1" AS ParceiroAnterior, Formulários!VendaImovelVendido!EmpVinculada AS Empresa, "1" AS Parceiro, Formulários!VendaImovelVendido!VendaCondPagto.Formulário!VenctoParcela AS DtMov, "1" AS Imovel, "2" AS Historico, "41" AS Plano3, Formulários!VendaImovelVendido!FinanceiraPadrao AS Financeira, Formulários!VendaImovelVendido!VendaCondPagto.Formulário!Documento AS Doc, Formulários!VendaImovelVendido!VendaCondPagto.Formulário!Complemento & " - " & Formulários!VendaImovelVendido!NomeParceiro AS Complem, Formulários!VendaImovelVendido!VendaCondPagto.Formulário!ValorInicial AS ValorCred, Formulários!VendaImovelVendido!CodImovel AS Agrupar, Formulários!VendaImovelVendido!VendaCondPagto.Formulário!VenctoParcela AS Vencto, Formulários!VendaImovelVendido!VendaCondPagto.Formulário!Integracao AS Integra, "C" AS Classifica, Formulários!VendaImovelVendido!Proprietario AS AtribuiParceiro, True AS Efetuado, Formulários!VendaImovelVendido!IndiceReajuste AS IndiceReajuste, Formulários!VendaImovelVendido!AplicarReajuste AS SofreReajuste, Formulários!VendaImovelVendido!VendaCondPagto.Formulário!ValorInicial AS ValorInicial, Formulários!VendaImovelVendido!VendaCondPagto.Formulário!CodPagtoImovel AS CodPagto;
